SELECT DISTINCT AdmFName1, AdmLName1 FROM schools WHERE CDSCode IN (
    SELECT cds FROM satscores WHERE NumGE1500 = (
        SELECT MAX(NumGE1500) FROM satscores
    )
);

SELECT SUM(Enrollment (Ages 5-17)) AS TotalEnrollment
FROM frpm
WHERE School Name = 'State Special School' AND `Academic Year` = '2014-2015' AND EdOpsCode = 'SSS';

SELECT COUNT(client_id) FROM client WHERE gender = 'M' AND district_id IN (
    SELECT district_id FROM district ORDER BY A15 DESC LIMIT 1 OFFSET 1
)

SELECT CAST(SUM(CASE WHEN T1.label = '+' AND T2.element = 'Cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT DISTINCT c.name FROM cards c
JOIN foreign_data fd ON c.uuid = fd.uuid
WHERE c.availability = 'paper' AND fd.language = 'Japanese';

SELECT SUM(CAST(SUBSTRING_INDEX(manaCost, '/', 1) AS REAL)) AS total_unconverted_mana
FROM cards
WHERE artist = 'Rob Alexander';

SELECT CAST(SUM(CASE WHEN isOnlineOnly = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(id) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT s.name, st.translation FROM sets s
JOIN set_translations st ON s.code = st.setCode
WHERE s.id = 5;

SELECT COUNT(DISTINCT s.id) FROM sets s
JOIN set_translations st ON s.code = st.setCode
WHERE st.language = 'Italian' AND st.translation IS NOT NULL AND s.baseSetSize < 100;

SELECT AVG(id), MAX(COUNT(language)) AS common_language
FROM sets
WHERE releaseDate BETWEEN '2012-01-01' AND '2015-12-31';

SELECT SUM(FavoriteCount) AS TotalFavoriteCount
FROM posts
WHERE OwnerUserId = 686 AND YEAR(CreationDate) = 2011;

SELECT CAST(COUNT(CASE WHEN T2.Name = 'Teacher' THEN T1.Id ELSE NULL END) AS REAL) * 100 / COUNT(T1.Id) AS PercentageOfTeachers
FROM users AS T1
JOIN badges AS T2 ON T1.Id = T2.UserId;

SELECT SUM(CASE WHEN T2.DisplayName = 'Mornington' THEN T1.ViewCount ELSE 0 END) - SUM(CASE WHEN T2.DisplayName = 'Amos' THEN T1.ViewCount ELSE 0 END) AS DifferenceInViewCount
FROM posts AS T1
JOIN users AS T2 ON T1.OwnerUserId = T2.Id;

SELECT COUNT(DISTINCT u.Id) FROM users u
JOIN posts p ON u.Id = p.OwnerUserId
WHERE u.Location = 'United Kingdom' AND p.FavoriteCount >= 4;

SELECT superhero_name FROM superhero WHERE id IN (
    SELECT hero_id FROM hero_attribute WHERE attribute_name = 'Durability' AND attribute_value < 50
)

SELECT superhero_name FROM superhero WHERE id IN (
    SELECT hero_id FROM hero_power GROUP BY hero_id ORDER BY COUNT(power_id) DESC LIMIT 1
)

SELECT SUM(CASE WHEN T2.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN T2.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id;

SELECT superhero_name, AVG(height_cm) AS average_height
FROM superhero
GROUP BY superhero_name;

SELECT superhero_name FROM superhero WHERE id IN (
    SELECT hero_id FROM hero_attribute WHERE attribute_name = 'Speed' ORDER BY attribute_value DESC LIMIT 1
)

SELECT CAST(SUM(CASE WHEN T2.gender_id = 1 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN T2.gender_id = 2 THEN 1 ELSE 0 END) AS ratio
FROM superhero AS T1
JOIN gender AS T2 ON T1.gender_id = T2.id;

SELECT superhero.full_name FROM superhero 
JOIN colour ON superhero.eye_colour_id = colour.id 
WHERE colour.colour = 'Blue';

SELECT superhero.superhero_name FROM superhero 
JOIN hero_attribute ON superhero.id = hero_attribute.hero_id 
WHERE hero_attribute.attribute_value BETWEEN 75 AND 80;

SELECT SUM(CASE WHEN T2.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN T2.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id;

SELECT COUNT(*) * 100 / (SELECT COUNT(*) FROM Patient WHERE YEAR(Birthday) BETWEEN '1930-01-01' AND '1940-12-31') AS Percentage_Inpatient
FROM Patient
WHERE Admission = '+';

SELECT MAX(YEAR(Birthday)) - MIN(YEAR(Birthday)) AS AgeGap
FROM Patient
WHERE tg >= 200;

SELECT CASE WHEN SUM(CASE WHEN T1.SEX = 'M' AND T2.CRE >= 1.5 THEN 1 ELSE 0 END) > SUM(CASE WHEN T1.SEX = 'F' AND T2.CRE >= 1.5 THEN 1 ELSE 0 END) THEN 'True' ELSE 'False' END AS Result
FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID;

SELECT Diagnosis FROM Patient WHERE ID IN (
    SELECT ID FROM Laboratory WHERE TG < 200 ORDER BY TG DESC LIMIT 1
)

SELECT AVG(COUNT(event_id)) / COUNT(DISTINCT event_name) AS average_attendance
FROM event
WHERE type = 'Meeting' AND YEAR(event_date) = 2020;

SELECT SUM(budget.spent) AS total_spent_for_food
FROM budget
WHERE budget.category = 'Food';

SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT event_name FROM event WHERE event_id IN (
    SELECT link_to_event FROM expense WHERE category = 'Parking'
) AND cost < (SELECT SUM(cost) / COUNT(event_id) FROM expense WHERE category = 'Parking');

SELECT CAST(SUM(CASE WHEN T2.type = 'Meeting' THEN T1.cost ELSE 0 END) AS REAL) * 100 / COUNT(T2.event_id) AS percentage_of_meeting_cost
FROM expense AS T1
JOIN event AS T2 ON T1.link_to_event = T2.event_id;

SELECT MAX(Consumption) AS HighestMonthlyConsumption
FROM yearmonth
WHERE STRFTIME('%Y', Date) = '2012';

SELECT COUNT(TransactionID) 
FROM transactions_1k 
WHERE Date = '2012-08-26' AND Time < '13:00:00' AND Currency = 'CZK';
